  c = mix(c, vec3(1.0, 0.93, 0.80), smoothstep(22.0, 10.0, d) * 0.6);
  // a whisper of rose lift around the cloud bank (light scattered off the clouds)
  c += vec3(0.08, 0.03, 0.04) * exp(-length((p - vec2(300.0, 90.0)) / vec2(320.0, 110.0)));
  c += (h21(gl_FragCoord.xy) - 0.5) / 255.0;
